SET @task_id=208;
SELECT 'TASK' AS section,id,tenant_id,task_type,mode,status,primary_stage,blocking_reason,group_count,expected_pull_count,FROM_UNIXTIME(started_at/1000) started_at,FROM_UNIXTIME(last_business_executed_at/1000) last_business_at FROM pull_task WHERE id=@task_id;
SELECT 'SETTING' AS section,s.* FROM pull_task_standard_setting s WHERE task_id=@task_id;
SELECT 'EXECUTION' AS section,id,seq,source_file_name,attempt_no,group_jid,execution_status,stage,manual_paused,valid_member_count,wait_resource_type,reason_code,reason_message,active_pull_wave_id,active_puller_group_account_id,puller_assignment_seq,FROM_UNIXTIME(started_at/1000) started_at,FROM_UNIXTIME(finished_at/1000) finished_at,FROM_UNIXTIME(last_business_executed_at/1000) last_business_at,FROM_UNIXTIME(next_run_at/1000) next_run_at,lock_owner,FROM_UNIXTIME(lock_expires_at/1000) lock_expires_at,FROM_UNIXTIME(updated_at/1000) updated_at FROM pull_task_group_execution WHERE task_id=@task_id ORDER BY seq,attempt_no;
SELECT 'MATERIAL' AS section,m.group_execution_id,m.pull_status,m.pull_reason_code,COUNT(*) n,MIN(m.pull_failure_count) min_failures,MAX(m.pull_failure_count) max_failures,FROM_UNIXTIME(MAX(m.pull_result_at)/1000) last_result FROM pull_task_material_member m JOIN pull_task_group_execution e ON e.id=m.group_execution_id AND e.tenant_id=m.tenant_id WHERE e.task_id=@task_id GROUP BY m.group_execution_id,m.pull_status,m.pull_reason_code;
SELECT 'WAVE' AS section,id,group_execution_id,wave_no,wave_type,wave_status,planned_call_count,next_call_seq,FROM_UNIXTIME(next_dispatch_at/1000) next_dispatch_at,FROM_UNIXTIME(dispatch_completed_at/1000) dispatch_completed_at,FROM_UNIXTIME(settled_at/1000) settled_at,FROM_UNIXTIME(created_at/1000) created_at,FROM_UNIXTIME(updated_at/1000) updated_at FROM pull_task_pull_wave WHERE task_id=@task_id ORDER BY group_execution_id,wave_no;
SELECT 'CALL_SUMMARY' AS section,group_execution_id,puller_account_id,call_status,reason_code,COUNT(*) n,SUM(planned_material_count) materials,ROUND(AVG((result_at-submitted_at)/1000),2) avg_result_seconds,MAX((result_at-submitted_at)/1000) max_result_seconds,FROM_UNIXTIME(MIN(submitted_at)/1000) first_submit,FROM_UNIXTIME(MAX(submitted_at)/1000) last_submit FROM pull_task_pull_call WHERE task_id=@task_id GROUP BY group_execution_id,puller_account_id,call_status,reason_code;
SELECT 'ROLE' AS section,a.id,a.group_execution_id,a.account_id,a.role_type,a.role_seq,a.membership_status,a.membership_reason_code,a.admin_status,a.availability_status,a.unavailable_reason_code,FROM_UNIXTIME(a.cooldown_until/1000) cooldown_until,FROM_UNIXTIME(a.joined_at/1000) joined_at,FROM_UNIXTIME(a.released_at/1000) released_at,FROM_UNIXTIME(a.updated_at/1000) updated_at,ac.protocol_id FROM pull_task_group_account a JOIN account ac ON ac.id=a.account_id WHERE a.task_id=@task_id ORDER BY a.group_execution_id,a.role_type,a.id;
SELECT 'QUERY_SUMMARY' AS section,group_execution_id,purpose,protocol_backend,query_status,error_code,COUNT(*) n,MAX(attempt_no) max_attempts,ROUND(AVG((completed_at-requested_at)/1000),2) avg_seconds,FROM_UNIXTIME(MAX(requested_at)/1000) last_requested,FROM_UNIXTIME(MAX(completed_at)/1000) last_completed FROM pull_task_member_query WHERE task_id=@task_id GROUP BY group_execution_id,purpose,protocol_backend,query_status,error_code;
SELECT 'ACTION_SUMMARY' AS section,group_execution_id,action_type,action_status,reason_code,COUNT(*) n,FROM_UNIXTIME(MAX(submitted_at)/1000) last_submitted,FROM_UNIXTIME(MAX(result_at)/1000) last_result FROM pull_task_account_action WHERE task_id=@task_id GROUP BY group_execution_id,action_type,action_status,reason_code;
